    }
    Ok((acl, LocalAllocation(descriptor as HLOCAL)))
}

fn trustee_for_sid(sid: PSID) -> TRUSTEE_W {
    TRUSTEE_W {
        pMultipleTrustee: null_mut(),
        MultipleTrusteeOperation: 0,
        TrusteeForm: TRUSTEE_IS_SID,
        TrusteeType: TRUSTEE_IS_UNKNOWN,
        ptstrName: sid as *mut u16,
    }
}

struct AppContainerSid(PSID);

impl AppContainerSid {
    fn derive(name: &str) -> Result<Self> {
        let name = wide_nul(OsStr::new(name))?;
        let mut sid = null_mut();
        let status = unsafe { DeriveAppContainerSidFromAppContainerName(name.as_ptr(), &mut sid) };
        if status < 0 || sid.is_null() {
            bail!("foreign-process AppContainer SID derivation failed");
        }
        Ok(Self(sid))
    }
}

impl Drop for AppContainerSid {
    fn drop(&mut self) {
        unsafe { FreeSid(self.0) };
    }
}

struct LocalAllocation(HLOCAL);

impl Drop for LocalAllocation {
    fn drop(&mut self) {
        if !self.0.is_null() {
            unsafe { LocalFree(self.0) };
        }
    }
}

fn wide_nul(value: &OsStr) -> Result<Vec<u16>> {
    let mut wide = value.encode_wide().collect::<Vec<_>>();
    if wide.contains(&0) {
        bail!("foreign-process sandbox path contains NUL");
    }
    wide.push(0);
    Ok(wide)
}

